contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We accept an amount to send into c and a boolean indicating whether the caller
    // should be the owner or not. The test drives c so that withdrawAll is invoked
    // by msg.sender (the caller of run). On the original P contract this will only
    // succeed in causing a decrease of c's balance when the caller is the owner.
    // The mutant inverts the check so a non-owner can withdraw; we assert that
    // only an owner-call can reduce c's balance.
    function run(uint depositAmount, bool callerIsOwner) public payable {
        // Ensure this contract has enough balance to fund the deposit into c
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // Record balance before
        uint balBefore = address(c).balance;

        // Send depositAmount to c by invoking its fallback (payable). The fallback increments depositsCount.
        // We forward ETH in the call to c by using low-level call via this contract's payable fallback.
        // Use c.call via address(c).call is not allowed by rules; instead use c.sendMoney with onlyOwner guard
        // but sendMoney is onlyOwner-protected, can't use. Instead, deposit by sending ETH directly to c via payable(address(c)).call.
        // However we're only allowed to interact through c's public/external surface; fallback payable can be triggered by
        // calling payable(address(c)).call{value: depositAmount}(""); that's allowed since it is an external call to the contract address.
        (bool ok,) = address(c).call{value: depositAmount}("");
        require(ok, "deposit failed");

        // Now attempt to trigger withdrawAll as the caller of this function.
        // If callerIsOwner == true, we must be the owner of c. The test harness should arrange deployment so that
        // when callerIsOwner is true, this contract is the owner. That can be achieved by deploying c with this contract as sender.
        // Conversely, when false, the caller is not owner.

        // Call withdrawAll (may revert depending on onlyOwner). We capture whether it reverted.
        bool didRevert;
        try c.withdrawAll() {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        uint balAfter = address(c).balance;

        // The distinguishing property: if the call did not revert, then the balance must have decreased only when the caller is the owner.
        // That is, for the original contract P: a successful withdrawAll call (no revert) implies callerIsOwner == true and balAfter < balBefore.
        // For the mutant M: withdrawAll is callable by non-owners and will reduce balance when callerIsOwner == false, violating this rule.
        assert((didRevert || (callerIsOwner && balAfter < balBefore)));
    }

    // allow this contract to receive ETH for funding deposits
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(true);
        bool reverted;
        // The call must be top-level and observe whether it reverts when invoked by `caller`.
        // We simulate the caller by using a low-level call from this contract: delegate to c via call
        // but calls must be direct on c; so we rely on the fact that withdrawAll checks msg.sender.
        // To have msg.sender == caller, the only way is for this test to be called by caller externally.
        // Therefore enforce that the externally supplied caller is the tx.origin/ msg.sender of this run.
        // Check that the caller parameter matches msg.sender to ensure the rule is about the actual caller.
        require(caller == msg.sender);
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        // General rule: withdrawAll should revert unless the caller is the contract's owner.
        // We express that as: if the call did NOT revert then the caller must be the owner.
        // We cannot read owner directly except via its public getter, which exists as `owner()`.
        assert(reverted || caller == c.owner());
    }
    receive() external payable { }
}

