pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: attacker address (caller of sendMoney) and amount to send out
    function testFuzz_property(address caller, uint256 value, bytes memory data) public {
        // keep caller non-zero to be a valid EOA candidate and avoid trivial zero address
        vm.assume(caller != address(0));
        // bound value so it fits within some reasonable testing range and to allow vm.deal
        uint256 amount = bound(value, 0, 1 ether);

        // Fund the contract so withdrawAll / sendMoney can send out funds
        // Use the deployer (this test contract) to send Ether to c
        vm.deal(address(this), 1 ether);
        // send some funds to c by calling its fallback via a low-level call with value
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent, "funding failed");

        // Ensure initial balance recorded via public getter (address(c).balance)
        uint256 before = address(c).balance;

        // Now have 'caller' attempt to invoke sendMoney to withdraw 'amount' to itself
        // For this we need caller to be able to send a call to c; vm.prank simulates that EOA
        // Ensure caller has enough balance to cover msg.value if any; sendMoney is non-payable for caller here
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        // call sendMoney with target = caller, value = amount, data = empty
        // If contract has correct onlyOwner modifier, only owner (deployer) can call this and it will NOT be callable by caller
        // If mutated, caller (not owner) will be allowed and c will transfer funds out reducing address(c).balance
        try c.sendMoney(caller, amount, data) {
            // swallow any returns; success or silent failure is acceptable
        } catch {
            // ignore revert; behavior difference will be captured by balance change
        }

        uint256 after = address(c).balance;

        // General rule: In the correct contract, non-owner callers cannot withdraw the contract balance via sendMoney, so balance must remain the same.
        // The mutant (inverted onlyOwner) allows non-owner to withdraw, so for some fuzzed inputs (caller != owner and amount > 0 and amount <= before) the balance will decrease.
        // Assert that balance did NOT decrease (this holds for the reference for all inputs); the mutant will fail this assertion for some inputs.
        assertTrue(after == before);
    }
}

