pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: attacker address (as caller) and amount to send with sendMoney
    function testFuzz_property(address caller, uint256 value) public {
        // keep value within reasonable bounds: not more than 1 ether
        value = bound(value, 0, 1 ether);

        // fund the contract so there is something to withdraw if withdraw/send triggers
        vm.deal(address(this), 2 ether);
        // send 1 ether into c so it has balance to possibly be withdrawn
        payable(address(c)).transfer(1 ether);

        // deploy adversarial callee which will forward any funds it receives back (or do nothing) ---
        // here we use a benign callee that accepts funds (fallback payable). The difference in behavior
        // stems from who is allowed to *withdraw* via sendMoney's call; by calling sendMoney with
        // calldata that triggers a transfer of contract funds, the inverted onlyOwner will allow a non-owner
        // caller to siphon funds. We need a callee that will accept funds so the low-level call in sendMoney
        // succeeds and can receive transferred value if the contract tries to send.
        Callee callee = new Callee();

        // record pre-call contract balance
        uint256 beforeBalance = address(c).balance;

        // make the call as the fuzzed caller
        vm.deal(caller, 1 ether); // ensure caller has ETH to send if desired
        vm.prank(caller);
        // call sendMoney with callee address, value, and empty data; the contract's sendMoney will perform
        // a low-level call to callee; if onlyOwner is inverted, a non-owner caller can cause withdrawal via that call
        // We send along zero value from the caller to the contract; the value parameter is passed to c.sendMoney
        c.sendMoney(address(callee), value, "");

        // single assertion: in the correct contract, regardless of caller and value arguments, the contract's balance
        // must remain equal to beforeBalance because only the owner can initiate withdrawals via sendMoney/withdrawAll;
        // the mutant that inverts onlyOwner allows some caller/values to reduce the contract balance, causing this assert
        // to fail for some inputs.
        assertTrue(address(c).balance == beforeBalance);
    }
}

// minimal callee that accepts funds
contract Callee {
    fallback() external payable {}
    receive() external payable {}
}

