pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: caller will be fuzzed address, value is fuzzed amount, data is fuzzed bytes
    function testFuzz_property(address caller, uint256 value, bytes memory data) public {
        // admissible domain: value must be <= 1 ether to keep vm.deal reasonable and avoid overflow in test environment
        value = bound(value, 0, 1 ether);

        // Ensure the contract has some initial balance to observe any outgoing transfer effect
        address funder = address(0xBEEF);
        vm.deal(funder, 1 ether);
        vm.prank(funder);
        (bool s, ) = payable(address(c)).call{value: 1 ether}("");
        require(s);

        uint256 before = address(c).balance;
        // The reference only allows the owner (deployer) to invoke sendMoney to cause transfers out.
        // So when the owner calls sendMoney, the contract balance should remain unchanged by outsider-triggered withdrawals.
        // We will make the fuzzed caller invoke sendMoney; in the reference, if caller == owner, call is allowed
        // and may cause transfer; however the general rule we assert is: when the owner calls sendMoney, the contract
        // balance does not decrease as a result of being invoked by owner via sendMoney to an arbitrary target with arbitrary data.
        // This rule is true for the reference for all inputs because onlyOwner requires msg.sender == owner.
        // The mutant inverts onlyOwner, so for some caller/address combinations the contract balance will change when non-owner calls.

        // We restrict the assertion to the owner being the caller so the reference's onlyOwner check permits owner actions,
        // and in the reference such an owner-invoked sendMoney will not allow arbitrary non-owner withdrawal (owner is allowed but
        // behavior is consistent). To let the fuzzer still find differences we allow caller to vary but assert only in the owner case.
        // Ensure caller equals owner for the assertion to be a universal property: for any data/value, when owner invokes sendMoney,
        // the contract's balance remains >= previous balance (no unexpected outgoing caused by inverted check for non-owner).

        address owner = address(this); // Note: in setUp we deployed c with this contract as deployer, so this is owner
        // sanity: owner must equal deployer
        // fund the caller so it can send value
        vm.deal(owner, 1 ether);

        // Owner invokes sendMoney; use vm.prank to set msg.sender
        vm.prank(owner);
        // call sendMoney with target = caller (fuzzed address), value and data (fuzzed)
        // sendMoney is not payable in interface but calls target with value; so we need to send value from the contract's balance, not from msg.sender
        c.sendMoney(caller, value, data);

        uint256 after = address(c).balance;

        // Single assertion: in the reference, when the owner calls sendMoney, the contract balance cannot decrease below zero and
        // should be <= initial but in correct contract only owner can cause withdraws and behavior is controlled; specifically here
        // we assert that after the owner invoked sendMoney the contract's balance is <= before (no unexpected increase). This holds
        // for the reference for all inputs; the mutant that inverts onlyOwner will allow non-owner calls to trigger withdrawals, but
        // because we perform the call as owner this assertion holds on the reference for all inputs and is violated by the mutant for
        // some inputs where ownership check inversion changes who can withdraw.

        // The required single assertTrue reading c: check that balance is less-than-or-equal to previous balance
        // (this is a general monotonicity rule under owner-invocation in the reference)
        assertTrue(address(c).balance <= before);
    }
}

