pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: attacker (caller who will call sendMoney) and amount to fund c and to send
    function testFuzz_property(address attacker, uint256 sendValue) public {
        // keep attacker non-zero and sendValue in a reasonable range
        vm.assume(attacker != address(0));
        sendValue = bound(sendValue, 1, 1 ether);

        // deploy a reentrant callee that, when called, will call c.withdrawAll()
        ReentrantCaller re = new ReentrantCaller(c);

        // fund attacker and the contract c
        vm.deal(attacker, 1 ether);
        // fund c so there is something to withdraw
        vm.deal(address(this), sendValue);
        // send Ether into c by invoking its fallback via a raw call from this test contract
        (bool okFund,) = address(c).call{value: sendValue}("");
        require(okFund);

        // record balance before
        uint256 beforeBal = address(c).balance;

        // attacker will call sendMoney targeting the reentrant callee, passing empty data
        vm.prank(attacker);
        // send zero value along with sendMoney call (we fuzz sendValue only for initial funding)
        c.sendMoney(address(re), 0, "");

        // record balance after
        uint256 afterBal = address(c).balance;

        // General property: for the correct contract, a non-owner attacker invoking sendMoney
        // that causes the callee to re-enter and call withdrawAll must NOT decrease address(c).balance
        // (only the owner can withdraw). This holds for all inputs on the reference and is broken
        // by the mutant where onlyOwner is inverted.
        assertTrue(afterBal >= beforeBal);
    }
}

// adversarial helper that re-enters c by calling withdrawAll from its fallback
contract ReentrantCaller {
    C immutable target;
    constructor(C _t) { target = _t; }
    fallback() external payable {
        // try to call withdrawAll; ignore failures
        try target.withdrawAll() {
        } catch {}
    }
}

