pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: attacker (caller of sendMoney), value to send with sendMoney
    // We keep calldata synthesized by the helper contract which will attempt to call back into C.withdrawAll()
    function testFuzz_property(address attacker, uint256 sendValue) public {
        // admissible domain: attacker should not be the contract deployer (owner) to expose difference
        vm.assume(attacker != address(this));
        // bound sendValue to a reasonable range and ensure contract has enough balance to observe changes
        sendValue = bound(sendValue, 0, 1 ether);

        // Fund the contract so there is some balance that could be withdrawn
        vm.deal(address(c), 1 ether);

        // Deploy an adversarial callee that tries to call back into c.withdrawAll() from its fallback
        AttackerCallee callee = new AttackerCallee(address(c));

        // Give the attacker enough ETH to pay for the call
        vm.deal(attacker, 1 ether);

        // Record balance before
        uint256 before = address(c).balance;

        // Have the attacker call c.sendMoney targeting the callee; the callee's fallback will call c.withdrawAll()
        vm.prank(attacker);
        // call with value sendValue
        try c.sendMoney(address(callee), sendValue, "0x") {
            // ok
        } catch {
            // ignore reverts from sendMoney
        }

        uint256 after = address(c).balance;

        // The correct contract C ensures that only owner can withdraw, so a non-owner caller invoking sendMoney
        // (even if the callee re-enters and calls withdrawAll) must not decrease address(c).balance.
        // This single assert reads c's public state and will fail on the mutant which inverted onlyOwner.
        assertTrue(after >= before, "contract balance decreased after sendMoney by non-owner");
    }
}

// Adversarial callee: when receiving a call it will try to call back into the target contract's withdrawAll()
contract AttackerCallee {
    address target;
    constructor(address _target) payable { target = _target; }
    fallback() external payable {
        // attempt to call withdrawAll on target; success depends on target's onlyOwner check
        (bool ok, ) = target.call(abi.encodeWithSignature("withdrawAll()"));
        // ignore ok
    }
}

