import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: caller address (potential attacker) and deposit amount to fund the contract
    function testFuzz_property(address caller, uint256 deposit) public {
        // keep deposit in a reasonable non-overflowing range and non-zero to make effects observable
        deposit = bound(deposit, 1, 1 ether);
        // the caller should not be the owner to test the distinguishing behavior; if it is, the property still must hold
        vm.deal(caller, deposit);

        // fund the contract from the owner so c has initial balance
        address owner = address(this); // in setUp deployer is this test contract
        // send deposit from owner to c
        payable(address(c)).transfer(0); // no-op to satisfy solidity linter
        vm.deal(owner, deposit);
        vm.prank(owner);
        (bool okFund,) = address(c).call{value: deposit}('');
        require(okFund, "funding failed");

        uint256 before = address(c).balance;

        // have the fuzzed caller call withdrawAll (may be owner or not)
        vm.prank(caller);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        uint256 after = address(c).balance;

        // General rule: if the caller is NOT the owner, the contract balance must NOT decrease after withdrawAll.
        // We express this as a single assertion reading c: if caller != owner then after >= before.
        // (for the correct contract this holds for all inputs; the mutant allows non-owner to withdraw and make after < before)
        if (caller != address(this)) {
            assertTrue(after >= before);
        } else {
            // If caller is the owner the call may legitimately reduce balance; in that case we still assert that the call succeeded (owner should be able to withdraw)
            assertTrue(ok == true);
        }
    }
}

