pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz the caller address and an amount to seed the contract balance.
    // General rule: For every caller, if the caller is NOT the owner then calling withdrawAll MUST NOT change address(c).balance.
    // The mutant removes the onlyOwner guard and thus some non-owner caller will be able to reduce address(c).balance.
    function testFuzz_property(address caller, uint256 seedAmount) public {
        // Keep domain wide but sensible: seedAmount > 0 and within balanceable range
        seedAmount = bound(seedAmount, 1, 1 ether);

        // Ensure caller is not the zero address (avoid weirdness) and not the owner
        vm.assume(caller != address(0));
        vm.assume(caller != address(this)); // avoid test contract
        vm.assume(caller != address(c));

        // Fund caller so they can send Ether to c if needed
        vm.deal(caller, seedAmount);

        // Owner (deployer of C) is address(this) in setUp; fund owner to deposit as well
        vm.deal(address(this), seedAmount);

        // Deposit Ether into c by making owner call fallback via pranked low-level call
        // Use owner to send seedAmount into c so c has positive balance
        vm.prank(address(this));
        (bool okOwner, ) = address(c).call{value: seedAmount}("");
        require(okOwner, "owner deposit failed");

        // Record balance before non-owner tries withdrawAll
        uint256 before = address(c).balance;
        // If caller happens to be owner, the rule is vacuously about non-owners only; skip such inputs
        vm.assume(caller != address(this));

