        // and then assert that c.sendMoney did not revert. But we cannot perform the transfer earlier in the function (it would change state),
        // so instead we perform it here as a check and then assert using its result.

        // Perform a plain transfer to check target is non-reverting for this value
        bool plainSendSucceeded;
        // use low-level call to transfer value to target from this contract
        (plainSendSucceeded, ) = target.call{value: value}("\x00");

        // If the plain transfer succeeded (target's fallback/receive didn't revert), then c.sendMoney must not have reverted
        assert(!plainSendSucceeded || !reverted);
    }

