// Helper that either reverts on receiving a call (fallback) or accepts funds (does nothing)
contract ReverterOrAcceptor {
    bool public doRevert;
    constructor(bool _doRevert) payable {
        doRevert = _doRevert;
    }
    fallback() external payable {
        if (doRevert) revert("revert on purpose");
    }
}

