pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: caller (address) and amount to send out of the contract to target
    function testFuzz_property(address caller, uint256 amount, bytes memory data) public {
        // keep caller non-zero and distinct from the owner to allow the fuzzer to explore non-owner cases
        vm.assume(caller != address(0));
        vm.assume(caller != address(this)); // ensure not the test deployer; owner is deployer of C in setUp()

        // Fund the contract with some ETH so sendMoney can transfer value out
        uint256 seedFund = 1 ether;
        vm.deal(address(this), seedFund);
        // send seedFund into contract from this test contract
        (bool s,) = address(c).call{value: seedFund}("");
        require(s);

        // Deploy an adversarial helper that will accept funds and do nothing (a normal contract)
        Receiver recv = new Receiver();

        // Bound amount to not exceed contract balance (but allow zero too)
        uint256 bounded = amount % (address(c).balance + 1);

        // If the caller is owner (deployer in setUp), then behavior allowed; we want to check that
        // reference contract only permits owner to cause balance to decrease. We fuzz caller to be
        // potentially non-owner. For non-owner callers, reference should not change contract balance.

        uint256 before = address(c).balance;

        // Make the call as the fuzzed caller, sending no value from caller (sendMoney sends from contract)
        vm.prank(caller);
        // call sendMoney with target = recv, value = bounded, data = data
        try c.sendMoney(address(recv), bounded, data) {
            // no revert
        } catch {
            // ignore revert; still check balance property
        }

        uint256 after = address(c).balance;

        // General rule (single assertion): If the caller is NOT the owner, the contract balance must remain unchanged
        // The reference implementation enforces this (only owner can make the contract send funds), the mutant
        // removes the check so for some non-owner caller + amount the balance will decrease.
        if (caller != address(this)) {
            assertTrue(after == before);
        } else {
            // If caller is owner (the test contract address), it's allowed to change balance; assertTrue still must hold
            // but in that case the reference permits change; to keep single assertTrue requirement, we assert a tautology
            // about reading the contract (owner may change balance). We still must emit exactly one assertTrue call
            assertTrue(after <= before);
        }
    }
}

